window.VeilGardeData.files["Tests-VeilGardeLensTests"] = {"group":"Tests-VeilGardeLensTests","files":[{"path":"Tests/VeilGardeLensTests/CLIPParityTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,44]],"header":{"lines":[1,9],"target":"VeilGardeLensTests","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1857,"scopes":[["X","LensMLXSuites",null,"",17,17,[17,24],44,null,-1,0,"a"],["S","CLIPParity",null,"",18,19,[19,22],43,null,0,0,"a"],["v","weights",null,"static",22,22,[22,33],25,[21,21],1,0,"a"],["f","parity",[],"",27,28,[28,29],42,null,1,0,"a"]],"old":"","new":"//\n//  CLIPParityTests.swift\n//  VeilGardeLensTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The CLIP vision tower against Hugging Face's on the same pixels: every image's\n//        embedding within cosine 0.9999, and the router's category call (the argmax over its\n//        five prompts) the same. Skipped when the weights are not on this Mac.\n//\n\nimport Foundation\nimport MLX\nimport Testing\nimport VeilGardeCore\n@testable import VeilGardeLens\n\nextension LensMLXSuites {\n    @Suite(\"CLIP vision against Hugging Face\", .serialized)\n    struct CLIPParity {\n        static let fixture = Fixture.url(\"clip_parity.safetensors\")\n        /// The work area's weights folder holds the tower (`veilgarde weights import-clip`).\n        static var weights: URL? {\n            if let area = WorkArea.resolve() { WeightLocator.shared.register(area.root.appendingPathComponent(\"weights\", isDirectory: true)) }\n            return WeightLocator.shared.url(.clipVision)\n        }\n\n        @Test(\"embeddings within cosine 0.9999 of HF's, categories equal\", .enabled(if: weights != nil))\n        func parity() throws {\n            let f = try SafetensorsFile(url: Self.fixture)\n            let pixels = try f.uint8(\"pixels\"), expected = try f.float32(\"embeds\"), logits = try f.float32(\"logits\")\n            let n = try f.tensor(\"pixels\").shape[0]\n            let ours = try CLIPLens.shared.tower()(CLIPPreprocess.input(pixels: pixels, count: n)).asArray(Float.self)\n            let prompts = try SafetensorsFile(url: Fixture.repoRoot.appendingPathComponent(\"Sources/VeilGardeFlywheel/Resources/clip_prompts_v1.safetensors\")).float32(\"prompts\")\n            for i in 0..<n {\n                let a = Array(ours[(i * 512)..<((i + 1) * 512)]), b = Array(expected[(i * 512)..<((i + 1) * 512)])\n                let cos = zip(a, b).reduce(Float(0)) { $0 + $1.0 * $1.1 }\n                #expect(cos >= 0.9999, \"image \\(i): cosine \\(cos)\")\n                let mine = (0..<5).map { k in 100 * zip(a, prompts[(k * 512)..<((k + 1) * 512)]).reduce(Float(0)) { $0 + $1.0 * $1.1 } }\n                let theirs = Array(logits[(i * 13)..<(i * 13 + 5)])\n                #expect(mine.firstIndex(of: mine.max()!) == theirs.firstIndex(of: theirs.max()!), \"image \\(i): category\")\n            }\n        }\n    }\n}\n"},{"path":"Tests/VeilGardeLensTests/Fixture.swift","status":"added","lang":"swift","hunks":[[1,0,1,24]],"header":{"lines":[1,9],"target":"VeilGardeLensTests","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1861,"scopes":[["E","Fixture",null,"",13,13,[13,13],24,null,-1,0,"a",[]],["f","url",["_"],"static",20,20,[20,43],20,null,0,8,"a"],["f","garde",["_"],"static",21,21,[21,45],21,null,0,8,"a"],["f","resource",["_"],"static",22,22,[22,48],22,null,0,8,"a"],["f","core",["_"],"static",23,23,[23,44],23,null,0,8,"a"]],"old":"","new":"//\n//  Fixture.swift\n//  VeilGardeLensTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Paths the Lens tests read by repo path: their own fixtures (Garde's feature dumps, the\n//        directional-signature fixture), the parity crops beside the Inference goldens, and the\n//        shipped resources.\n//\n\nimport Foundation\n\nenum Fixture {\n    static let repoRoot: URL = {\n        var url = URL(fileURLWithPath: #filePath)\n        while url.lastPathComponent != \"Tests\" { url.deleteLastPathComponent() }\n        return url.deletingLastPathComponent()\n    }()\n\n    static func url(_ name: String) -> URL { repoRoot.appendingPathComponent(\"Tests/VeilGardeLensTests/Fixtures/\\(name)\") }\n    static func garde(_ name: String) -> URL { repoRoot.appendingPathComponent(\"Tests/VeilGardeInferenceTests/Fixtures/garde/\\(name)\") }\n    static func resource(_ name: String) -> URL { repoRoot.appendingPathComponent(\"Sources/VeilGardeInference/Resources/\\(name)\") }\n    static func core(_ name: String) -> URL { repoRoot.appendingPathComponent(\"Tests/VeilGardeCoreTests/Fixtures/\\(name)\") }\n}\n"},{"path":"Tests/VeilGardeLensTests/LensParityTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,51]],"header":{"lines":[1,9],"target":"VeilGardeLensTests","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1866,"scopes":[["X","LensMLXSuites",null,"",15,15,[15,24],51,null,-1,0,"a"],["S","LensParityTests",null,"",16,17,[17,27],50,null,0,0,"a"],["f","featureDump",["name"],"",18,19,[19,46],32,null,1,0,"a"],["f","directionalSignature",[],"",34,35,[35,43],49,null,1,0,"a"]],"old":"","new":"//\n//  LensParityTests.swift\n//  VeilGardeLensTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The warp lens against Garde and the Python reference: the 256 × 19 tile feature matrix of each parity crop\n//        equals Garde's --dump-features output byte for byte, and the directional signature meets\n//        Garde's tolerances on the v4_a1_tilesig fixture. GPU suites, one at a time.\n//\n\nimport Foundation\nimport Testing\n@testable import VeilGardeLens\n\nextension LensMLXSuites {\n    @Suite(\"Lens parity with Garde and the Python reference\", .serialized)\n    struct LensParityTests {\n        @Test(\"the tile feature matrix equals Garde's dump byte for byte\", arguments: [\"crop_ben\", \"crop_fox\"])\n        func featureDump(name: String) throws {\n            let cg = try ImageDecoding.cgImage(contentsOf: Fixture.garde(\"\\(name).png\"))\n            let (map, geometry) = try WarpLens.tileFeatures(cgImage: cg)\n            #expect(map.tileRows == 16 && map.tileCols == 16 && map.featureCount == 19)\n            #expect(geometry.scoringWidth == 512 && geometry.scoringHeight == 512)\n            let ours = try map.dumpJSON(patchRows: 16, patchCols: 16, tilesPerPatch: 1)\n            let garde = try Data(contentsOf: Fixture.url(\"\\(name).features.json\"))\n            #expect(ours == garde, \"\\(name): the dumps differ\")\n            if ours != garde {\n                let a = try JSONSerialization.jsonObject(with: ours) as! [String: Any], b = try JSONSerialization.jsonObject(with: garde) as! [String: Any]\n                let fa = (a[\"features\"] as! [[NSNumber]]).flatMap { $0.map(\\.doubleValue) }, fb = (b[\"features\"] as! [[NSNumber]]).flatMap { $0.map(\\.doubleValue) }\n                Issue.record(\"max |Δ feature| \\(zip(fa, fb).map { abs($0 - $1) }.max() ?? -1)\")\n            }\n        }\n\n        @Test(\"the directional signature meets Garde's tolerances on the reference fixture\")\n        func directionalSignature() throws {\n            let object = try JSONSerialization.jsonObject(with: Data(contentsOf: Fixture.url(\"dirsig_fixture.json\"))) as! [String: Any]\n            let h = (object[\"height\"] as! NSNumber).intValue, w = (object[\"width\"] as! NSNumber).intValue\n            let img = (object[\"image\"] as! [NSNumber]).map(\\.floatValue), sig = (object[\"sig\"] as! [NSNumber]).map(\\.floatValue)\n            let got = WarpDebug.directionalSignature(imageRGB: img, height: h, width: w, quantizeLikeCV2: true)\n            var raw: Float = 0, derived: Float = 0\n            for t in 0..<((h / 32) * (w / 32)) {\n                for f in 0..<21 {\n                    let d = abs(got[t * 21 + f] - sig[t * 21 + f])\n                    if f < 16 { raw = max(raw, d) } else { derived = max(derived, d) }\n                }\n            }\n            #expect(raw < 1e-3, \"raw energies max |Δ| \\(raw)\")\n            #expect(derived < 5e-3, \"log-ratios max |Δ| \\(derived)\")\n        }\n    }\n}\n"},{"path":"Tests/VeilGardeLensTests/LinkTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,15]],"header":{"lines":[1,7],"target":"VeilGardeLensTests","what":[6,6],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1870,"scopes":[["S","LensLinkTests",null,"",12,13,[13,21],15,null,-1,0,"a"],["f","reExportsCore",[],"",14,14,[14,31],14,null,0,8,"a"]],"old":"","new":"//\n//  LinkTests.swift\n//  VeilGardeLensTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The module links and re-exports Core.\n//\n\nimport Testing\nimport VeilGardeLens\n\n@Suite(\"Lens links\")\nstruct LensLinkTests {\n    @Test func reExportsCore() { #expect(!VeilGardeVersion.string.isEmpty) }\n}\n"},{"path":"Tests/VeilGardeLensTests/MLXGate.swift","status":"added","lang":"swift","hunks":[[1,0,1,21]],"header":{"lines":[1,10],"target":"VeilGardeLensTests","what":[6,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1872,"scopes":[["S","LensMLXSuites",null,"",20,21,[21,21],21,null,-1,8,"a"]],"old":"","new":"//\n//  MLXGate.swift\n//  VeilGardeLensTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The MLX suites run one at a time and only when asked: VEILGARDE_MLX_TESTS=1 (or\n//        FRIGATE_MLX_TESTS=1). Every GPU suite in this target nests under LensMLXSuites, which\n//        is serialized; run the targets with `swift test --no-parallel` too, so two MLX workloads\n//        never overlap.\n//\n\nimport Foundation\nimport Testing\n\nlet mlxTests: Bool = {\n    let env = ProcessInfo.processInfo.environment\n    return env[\"VEILGARDE_MLX_TESTS\"] == \"1\" || env[\"FRIGATE_MLX_TESTS\"] == \"1\"\n}()\n\n@Suite(\"Lens: MLX, one suite at a time\", .enabled(if: mlxTests), .serialized)\nstruct LensMLXSuites {}\n"},{"path":"Tests/VeilGardeLensTests/ScorerTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,65]],"header":{"lines":[1,9],"target":"VeilGardeLensTests","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1873,"scopes":[["S","ScorerTests",null,"",18,19,[19,19],65,null,-1,0,"a"],["f","evaluatorsAgree",["key","file"],"",20,21,[21,59],28,null,0,0,"a"],["f","orientedPNG",["_"],"",31,31,[31,56],43,[30,30],0,0,"a"],["f","rgb",["_"],"",45,45,[45,42],51,null,0,0,"a"],["f","orientation",[],"",53,54,[54,30],64,null,0,0,"a"]],"old":"","new":"//\n//  ScorerTests.swift\n//  VeilGardeLensTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Frigate's XGBoostTreeModel (what the detector scores with) and Core's GBDTModel (what the\n//        trainer writes and evaluates) agree bit for bit on the shipped boosters; the decoder\n//        applies EXIF orientation exactly as Garde's NSImage path did.\n//\n\nimport CoreGraphics\nimport Foundation\nimport ImageIO\nimport Testing\nimport UniformTypeIdentifiers\n@testable import VeilGardeLens\n\n@Suite(\"Scorers and decoding\")\nstruct ScorerTests {\n    @Test(\"Frigate's evaluator and GBDTModel agree bit for bit\", arguments: [(\"warp\", \"warp_tile32.xgb.json\"), (\"fusion\", \"fusion_head.xgb.json\")])\n    func evaluatorsAgree(key: String, file: String) throws {\n        let reference = try JSONSerialization.jsonObject(with: Data(contentsOf: Fixture.core(\"boost_reference.json\"))) as! [String: Any]\n        let rows = ((reference[key] as! [String: Any])[\"rows\"] as! [[NSNumber]]).map { $0.map(\\.floatValue) }\n        let frigate = try TreeModelCache.shared.scorer(Fixture.resource(file))\n        let core = try GBDTModel.load(Fixture.resource(file))\n        #expect(frigate.featureCount == core.featureCount)\n        #expect(frigate.scoreBatch(rows) == core.scoreBatch(rows))\n    }\n\n    /// A 3×2 image whose pixels are all distinct, written with an EXIF orientation tag.\n    func orientedPNG(_ orientation: Int) throws -> Data {\n        var pixels = [UInt8]()\n        for i in 0..<6 { pixels += [UInt8(40 * i), UInt8(255 - 40 * i), UInt8(17 * i), 255] }\n        let provider = CGDataProvider(data: Data(pixels) as CFData)!\n        let image = CGImage(width: 3, height: 2, bitsPerComponent: 8, bitsPerPixel: 32, bytesPerRow: 12, space: CGColorSpace(name: CGColorSpace.sRGB)!,\n                            bitmapInfo: CGBitmapInfo(rawValue: CGImageAlphaInfo.premultipliedLast.rawValue), provider: provider, decode: nil,\n                            shouldInterpolate: false, intent: .defaultIntent)!\n        let data = NSMutableData()\n        let destination = CGImageDestinationCreateWithData(data as CFMutableData, UTType.png.identifier as CFString, 1, nil)!\n        CGImageDestinationAddImage(destination, image, [kCGImagePropertyOrientation: orientation] as CFDictionary)\n        #expect(CGImageDestinationFinalize(destination))\n        return data as Data\n    }\n\n    func rgb(_ image: CGImage) -> [UInt8] {\n        var buffer = [UInt8](repeating: 0, count: image.width * image.height * 4)\n        let ctx = CGContext(data: &buffer, width: image.width, height: image.height, bitsPerComponent: 8, bytesPerRow: image.width * 4,\n                            space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.noneSkipLast.rawValue)!\n        ctx.draw(image, in: CGRect(x: 0, y: 0, width: image.width, height: image.height))\n        return buffer\n    }\n\n    @Test(\"orientation 6 rotates clockwise and 1 leaves the pixels alone\")\n    func orientation() throws {\n        let upright = try ImageDecoding.cgImage(data: orientedPNG(1))\n        #expect(upright.width == 3 && upright.height == 2)\n        let rotated = try ImageDecoding.cgImage(data: orientedPNG(6))\n        #expect(rotated.width == 2 && rotated.height == 3)\n        let a = rgb(upright), b = rgb(rotated)\n        // Rotating 90° clockwise: the stored top-left (0,0) lands at the top-right of a 2-wide image.\n        #expect(Array(b[4..<7]) == Array(a[0..<3]))\n        // The stored bottom-left (0,1) lands at the top-left.\n        #expect(Array(b[0..<3]) == Array(a[12..<15]))\n    }\n}\n"}]};
